        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_fps_cashu_checksum_method_cashuwallet_balance_sat() != 58094) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_fps_cashu_checksum_method_cashuwallet_finish_top_up() != 24753) {
        return InitializationResult.apiChecksumMismatch
    }
